#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int frequenze[6] = {0};
    const int punti[6] = {[1] = 0, [2] = 25, [3] = 50, [4] = 75, [5] = 100};
    const size_t dim = sizeof(frequenze) / sizeof(frequenze[0]);
    char riga[128];
    int voto = 0;
    char extra = '\0';
    int totale = 0;

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%d %c", &voto, &extra) != 1 || voto < 1 || voto > 5) {
            fprintf(stderr, "Errore: voto non valido (atteso 1..5).\n");
            return EXIT_FAILURE;
        }
        ++frequenze[voto];
        ++totale;
    }
    if (totale == 0) {
        printf("Nessuna valutazione inserita.\n");
        return EXIT_SUCCESS;
    }

    int somma_voti = 0;
    int somma_punti = 0;
    size_t voto_modale = 1;
    for (size_t i = 1; i < dim; ++i) {
        printf("Voto %zu: %d (", i, frequenze[i]);
        for (int k = 0; k < frequenze[i]; ++k) {
            putchar('*');
        }
        printf(")\n");
        somma_voti += (int)i * frequenze[i];
        somma_punti += punti[i] * frequenze[i];
        if (frequenze[i] > frequenze[voto_modale]) {
            voto_modale = i;
        }
    }
    printf("Totale valutazioni: %d\n", totale);
    printf("Media voti: %.2f\n", (double)somma_voti / totale);
    printf("Gradimento medio: %.2f / 100\n", (double)somma_punti / totale);
    printf("Voto piu frequente: %zu (%d voti)\n", voto_modale, frequenze[voto_modale]);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    constexpr int MAX_STAZIONI = 20;
    double misure[MAX_STAZIONI] = {0};
    char riga[128];
    int n = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n, &extra) != 1 || n < 1 || n > MAX_STAZIONI) {
        fprintf(stderr, "Errore: numero di stazioni non valido (1..20).\n");
        return EXIT_FAILURE;
    }
    for (int i = 0; i < n; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%lf %c", &misure[i], &extra) != 1) {
            fprintf(stderr, "Errore: misura non valida alla stazione %d.\n", i);
            return EXIT_FAILURE;
        }
    }

    int valide = 0;
    int respinte = 0;
    int inizio = 0;
    int fine = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%d %d %c", &inizio, &fine, &extra) != 2) {
            fprintf(stderr, "Errore: formato interrogazione non valido.\n");
            return EXIT_FAILURE;
        }
        if (inizio < 0 || fine < inizio || fine >= n) {
            printf("Intervallo [%d..%d]: fuori dai limiti (validi 0..%d)\n",
                   inizio, fine, n - 1);
            ++respinte;
            continue;
        }
        double minimo = misure[inizio];
        double massimo = misure[inizio];
        double somma = 0.0;
        for (int i = inizio; i <= fine; ++i) {
            if (misure[i] < minimo) {
                minimo = misure[i];
            }
            if (misure[i] > massimo) {
                massimo = misure[i];
            }
            somma += misure[i];
        }
        int lunghezza = fine - inizio + 1;
        printf("Intervallo [%d..%d]: min=%.2f, max=%.2f, media=%.2f\n",
               inizio, fine, minimo, massimo, somma / lunghezza);
        ++valide;
    }
    printf("Interrogazioni valide: %d, respinte: %d\n", valide, respinte);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

size_t satura_array(int a[], size_t n, int minimo, int massimo);
void inverti_array(int a[], size_t n);
void stampa_array(const int a[], size_t n);

int main(void) {
    constexpr size_t MAX_CAMPIONI = 30;
    int campioni[MAX_CAMPIONI] = {0};
    char riga[128];
    int n_in = 0, minimo = 0, massimo = 0;
    char extra = '\0';
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %d %c", &n_in, &minimo, &massimo, &extra) != 3 ||
        n_in < 1 || n_in > (int)MAX_CAMPIONI || minimo > massimo ||
        minimo < -10'000 || massimo > 10'000) {
        fprintf(stderr, "Errore: intestazione non valida.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    for (size_t i = 0; i < n; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%d %c", &campioni[i], &extra) != 1 ||
            campioni[i] < -10'000 || campioni[i] > 10'000) {
            fprintf(stderr, "Errore: campione non valido.\n");
            return EXIT_FAILURE;
        }
    }
    printf("Originali: ");
    stampa_array(campioni, n);
    size_t mod = satura_array(campioni, n, minimo, massimo);
    inverti_array(campioni, n);
    printf("Elementi modificati: %zu\n", mod);
    printf("Elaborati: ");
    stampa_array(campioni, n);
    return EXIT_SUCCESS;
}

size_t satura_array(int a[], size_t n, int minimo, int massimo) {
    size_t mod = 0;
    for (size_t i = 0; i < n; ++i) {
        int orig = a[i];
        if (a[i] < minimo) { a[i] = minimo; }
        if (a[i] > massimo) { a[i] = massimo; }
        if (a[i] != orig) { ++mod; }
    }
    return mod;
}

void inverti_array(int a[], size_t n) {
    for (size_t i = 0; i < n / 2; ++i) {
        int tmp = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = tmp;
    }
}

void stampa_array(const int a[], size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (i > 0) { putchar(' '); }
        printf("%d", a[i]);
    }
    putchar('\n');
}

#include <stdio.h>
#include <stdlib.h>

constexpr size_t MAX_DIM = 6;

void stampa_matrice(const int m[][MAX_DIM], size_t righe, size_t colonne);
int somma_riga(const int m[][MAX_DIM], size_t riga, size_t colonne);
void trasponi(const int orig[][MAX_DIM], int trasp[][MAX_DIM], size_t righe, size_t colonne);

int main(void) {
    int mat[MAX_DIM][MAX_DIM] = {0}, trasp[MAX_DIM][MAX_DIM] = {0};
    char riga[128];
    int r_in = 0, c_in = 0;
    char extra = '\0';
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &r_in, &c_in, &extra) != 2 ||
        r_in < 1 || r_in > (int)MAX_DIM || c_in < 1 || c_in > (int)MAX_DIM) {
        fprintf(stderr, "Errore: dimensioni matrice non valide (1..6).\n");
        return EXIT_FAILURE;
    }
    size_t righe = (size_t)r_in, colonne = (size_t)c_in;
    for (size_t r = 0; r < righe; ++r) {
        for (size_t c = 0; c < colonne; ++c) {
            if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
                sscanf(riga, "%d %c", &mat[r][c], &extra) != 1 ||
                mat[r][c] < -1000 || mat[r][c] > 1000) {
                fprintf(stderr, "Errore: elemento matrice non valido.\n");
                return EXIT_FAILURE;
            }
        }
    }
    trasponi(mat, trasp, righe, colonne);
    printf("Matrice originale:\n");
    stampa_matrice(mat, righe, colonne);
    printf("Somma righe:");
    for (size_t r = 0; r < righe; ++r) { printf(" %d", somma_riga(mat, r, colonne)); }
    printf("\nSomma colonne:");
    for (size_t c = 0; c < colonne; ++c) { printf(" %d", somma_riga(trasp, c, righe)); }
    printf("\nMatrice trasposta:\n");
    stampa_matrice(trasp, colonne, righe);
    return EXIT_SUCCESS;
}

void stampa_matrice(const int m[][MAX_DIM], size_t righe, size_t colonne) {
    for (size_t r = 0; r < righe; ++r) {
        for (size_t c = 0; c < colonne; ++c) { printf("%4d", m[r][c]); }
        putchar('\n');
    }
}

int somma_riga(const int m[][MAX_DIM], size_t riga, size_t colonne) {
    int s = 0;
    for (size_t c = 0; c < colonne; ++c) { s += m[riga][c]; }
    return s;
}

void trasponi(const int orig[][MAX_DIM], int trasp[][MAX_DIM], size_t righe, size_t colonne) {
    for (size_t r = 0; r < righe; ++r) {
        for (size_t c = 0; c < colonne; ++c) { trasp[c][r] = orig[r][c]; }
    }
}

#include <stdio.h>
#include <stdlib.h>

size_t ordina_inserzione(int a[], size_t n);
int ricerca_lineare(const int a[], size_t n, int chiave);
int ricerca_binaria(const int a[], size_t n, int chiave);

int main(void) {
    constexpr size_t MAX_ELEM = 50;
    int dati[MAX_ELEM] = {0};
    char riga[128];
    int n_in = 0, chiave = 0;
    char extra = '\0';
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n_in, &extra) != 1 || n_in < 1 || n_in > (int)MAX_ELEM) {
        fprintf(stderr, "Errore: numero di elementi non valido (1..50).\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    for (size_t i = 0; i < n; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%d %c", &dati[i], &extra) != 1) {
            fprintf(stderr, "Errore: elemento non valido.\n");
            return EXIT_FAILURE;
        }
    }
    size_t spostamenti = ordina_inserzione(dati, n);
    printf("Array ordinato:");
    for (size_t i = 0; i < n; ++i) { printf(" %d", dati[i]); }
    printf("\nSpostamenti inserzione: %zu\n", spostamenti);
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%d %c", &chiave, &extra) != 1) {
            fprintf(stderr, "Errore: chiave non valida.\n");
            return EXIT_FAILURE;
        }
        printf("Chiave %d: lineare=%d, binaria=%d\n",
               chiave, ricerca_lineare(dati, n, chiave), ricerca_binaria(dati, n, chiave));
    }
    return EXIT_SUCCESS;
}

size_t ordina_inserzione(int a[], size_t n) {
    size_t spostamenti = 0;
    for (size_t i = 1; i < n; ++i) {
        int chiave = a[i];
        size_t j = i;
        while (j > 0 && a[j - 1] > chiave) {
            a[j] = a[j - 1];
            --j;
            ++spostamenti;
        }
        a[j] = chiave;
    }
    return spostamenti;
}

int ricerca_lineare(const int a[], size_t n, int chiave) {
    for (size_t i = 0; i < n; ++i) {
        if (a[i] == chiave) { return (int)i; }
    }
    return -1;
}

int ricerca_binaria(const int a[], size_t n, int chiave) {
    size_t sinistra = 0, destra = n;
    while (sinistra < destra) {
        size_t medio = sinistra + (destra - sinistra) / 2;
        if (a[medio] < chiave) { sinistra = medio + 1; } else { destra = medio; }
    }
    return (sinistra < n && a[sinistra] == chiave) ? (int)sinistra : -1;
}
